import{seeded as M}from"./city.min.js";import{dayOfYear as d,mix as x}from"./daylight.min.js";export const WEATHER={seed:20260929,chance:{mean:.35,swing:.25},start:[0,22],hours:[3,10],strength:[.45,1],lead:1.5,ramp:.75};export function wetChance(t,s=WEATHER){const r=Math.cos(2*Math.PI*(d(t)-355)/365);return s.chance.mean+s.chance.swing*r}export function mixSeed(t){let s=t>>>0;return s=Math.imul(s^s>>>16,73244475),s=Math.imul(s^s>>>16,73244475),((s^s>>>16)>>>0)%2147483646+1}export function daySpell(t,s=WEATHER){const r=t.getFullYear()*1e4+(t.getMonth()+1)*100+t.getDate(),n=M(mixSeed(s.seed+r));if(n()>=wetChance(t,s))return null;const o=([c,h])=>c+n()*(h-c),e=o(s.start);return{start:e,end:e+o(s.hours),strength:o(s.strength)}}function p(t,s,r){const n=Math.min(1,Math.max(0,(t-s)/r));return n*n*(3-2*n)}export function weatherAt(t,s=null,r=WEATHER){if(s==="rain")return{overcast:1,rain:1};if(s==="clear")return{overcast:0,rain:0};const n=t.getHours()+t.getMinutes()/60+t.getSeconds()/3600;let a=0,o=0;const e=new Date(t.getFullYear(),t.getMonth(),t.getDate()-1);for(const[c,h]of[[t,0],[e,24]]){const u=daySpell(c,r);if(!u)continue;const m=n+h,{start:l,end:f,strength:g}=u,{lead:i,ramp:y}=r;o=Math.max(o,g*Math.min(p(m,l,y),1-p(m,f-y,y))),a=Math.max(a,Math.min(p(m,l-i,i),1-p(m,f,i)))}return{overcast:Math.max(a,o),rain:o}}export function grayOf(t,s=1){const r=t>>16&255,n=t>>8&255,a=t&255,o=Math.min(255,(.2126*r+.7152*n+.0722*a)*s),e=c=>Math.min(255,Math.round(o*c));return e(.94)<<16|e(.97)<<8|e(1.04)}export function weathered(t,{overcast:s,rain:r}){const n=s;return{...t,skyTop:x(t.skyTop,grayOf(t.skyBottom,.82),.9*n),skyBottom:x(t.skyBottom,grayOf(t.skyBottom,.9),.85*n),clouds:x(t.clouds,grayOf(t.clouds,.72),.8*n),sun:t.sun*(1-.7*n),halo:t.halo*(1-n),warm:(t.warm||0)*(1-n),hemi:t.hemi*(1-.25*n),fill:t.fill*(1-.2*n),stars:t.stars*(1-n),moonShine:t.moonShine*(1-.9*n),cityLights:Math.min(1,t.cityLights+.3*n),overcast:s,rain:r}}export const RAIN={count:1400,box:{x:[-40,70],y:[-45,30],z:[-100,20]},fall:9,length:1.6,slant:.18};export function rainStreaks(t=RAIN,s=20260930){const r=M(s),{x:n,y:a,z:o}=t.box,e=([c,h])=>c+r()*(h-c);return Array.from({length:t.count},()=>[e(n),e(a),e(o),r()])}export function streakPositions(t,s,r=RAIN,n=new Float32Array(t.length*6)){const[a,o]=r.box.y,e=o-a;return t.forEach(([c,h,u,m],l)=>{const f=((o-h+s*r.fall+m*e)%e+e)%e,g=o-f,i=l*6;n[i]=c,n[i+1]=g,n[i+2]=u,n[i+3]=c,n[i+4]=g-r.length,n[i+5]=u+r.length*r.slant}),n}
